import { Component, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { TablaComponent, TableDefinition, AdvancedSearchFilter } from "../../../shared/tabla/tabla.component";
import { UsuarioService } from '../../../controllers/usuario.service';
import { Conditional } from '../../../controllers/super.service';
import { LocalStorageService } from '../../../services/localStorage/local-storage.service';

const TABLE_DEF: TableDefinition = {
  columns: [
    'id',
    'rfc',
    {
      key: 'name',
      header: 'Nombre',
    },
    {
      key: 'email',
      header: 'Correo Electrónico'
    },
    {
      key: 'user_type',
      header: 'Tipo de Usuario',
    },
    {
      key: 'created_at',
      header: 'Creado En',
      pipe: 'date'
    },
    {
      key: 'last_login',
      header: 'Último login',
      pipe: 'date'
    }
  ]
}

@Component({
  selector: 'app-usuarios-list',
  imports: [CommonModule, TablaComponent],
  templateUrl: './usuarios-list.html',
  styleUrl: './usuarios-list.css'
})
export class UsuariosList {
  public table = TABLE_DEF
  public relations = ['roles']
  public usuarioController = inject(UsuarioService)
  public storage = inject(LocalStorageService);
  public isUsuarioInterno: boolean;

  // View state for external users
  externosView: 'activos' | 'inactivos' = 'activos';

  // Conditionals for filtering
  internosConditionals: Conditional[] = [
    { key: 'user_type', operator: '=', value: 'INTERNO' }
  ];
  
  externosInactivosAdvancedFilters: AdvancedSearchFilter[];
  externosInactivosConditionals: Conditional[];
  externosActivosConditionals: Conditional[];

  constructor() {
    this.isUsuarioInterno = this.storage.esUsuarioInterno();

    const twoYearsAndADayAgo = new Date(Date.now() - (2 * 365 + 1) * 24 * 60 * 60 * 1000);
    const dateString = twoYearsAndADayAgo.toISOString().split('T')[0];

    this.externosActivosConditionals = [
      { key: 'user_type', operator: '=', value: 'EXTERNO' },
      { key: 'last_login', operator: '>=', value: dateString},      
    ];
    
    this.externosInactivosConditionals = [
      { key: 'user_type', operator: '=', value: 'EXTERNO' }
    ];

    this.externosInactivosAdvancedFilters = [
      {
        relation: '', // Using '' for base model query
        opWhere: true, // Use OR for the conditionals
        conditionals: [
          ['last_login', '<=', dateString],
          ['last_login', 'IS NULL', null]
        ],
        andConditionals: []
      }
    ];
  }

  // Control de pestañas activas
  pestanaActiva: 'internos' | 'externos' = 'internos';

  // Opciones de pestañas
  tabs = [
    {
      id: 'internos' as const,
      label: 'Internos',
      icono: 'bi-person',
      descripcion: 'Usuarios internos de la plataforma'
    },
    {
      id: 'externos' as const,
      label: 'Externos',
      icono: 'bi-person-badge',
      descripcion: 'Usuarios externos de la plataforma'
    }
  ];

  /**
   * Cambia a la pestaña especificada
   */
  cambiarPestana(pestana: 'internos' | 'externos'): void {
    this.pestanaActiva = pestana;
  }

  /**
   * Verifica si una pestaña está activa
   */
  isActive(pestana: 'internos' | 'externos'): boolean {
    return this.pestanaActiva === pestana;
  }

  /**
   * Obtiene la información de la pestaña activa
   */
  getPestanaActivaInfo() {
    return this.tabs.find(p => p.id === this.pestanaActiva);
  }

  /**
   * Sets the view for external users.
   * @param view The view to set.
   */
  setExternosView(view: 'activos' | 'inactivos'): void {
    this.externosView = view;
  }

  /**
   * Checks if the given view is the active one for external users.
   * @param view The view to check.
   */
  isExternosViewActive(view: 'activos' | 'inactivos'): boolean {
    return this.externosView === view;
  }
}
